import os,time,pickle
import jax, jax.numpy as jnp
import numpy as np
import scipy.optimize as opt
import tensorcircuit as tc
from tensorcircuit import gates
import quimb.tensor as qtn
tc.set_backend('jax')
n=32; nl=2; npar=465
with open('/tmp/psi.pkl','rb') as f: psi=pickle.load(f)
def conv(psi):
 out=[]
 for i,t in enumerate(psi.tensors):
  a=np.asarray(t.data)
  if i==0: out.append(jnp.asarray(a.reshape(1,a.shape[1],a.shape[0]),dtype=jnp.complex64))
  elif i==n-1: out.append(jnp.asarray(a.reshape(a.shape[0],a.shape[1],1),dtype=jnp.complex64))
  else: out.append(jnp.asarray(a.transpose(0,2,1),dtype=jnp.complex64))
 return out
tt=conv(psi)
neel=[]
for i in range(n):
 v=jnp.array([0,1],dtype=jnp.complex64) if i%2 else jnp.array([1,0],dtype=jnp.complex64)
 neel.append(v[None,:,None])
def apply(theta):
 c=tc.MPSCircuit(n,tensors=neel,center_position=0); gidx=0
 for layer in range(nl):
  bonds=range(0,n-1,2) if layer==0 else range(1,n-1,2)
  for b in bonds:
   p=theta[gidx*15:(gidx+1)*15]; c.apply_adjacent_double_gate(gates.su4_gate(p),b,b+1); gidx+=1
 return c
def loss(theta):
 c=apply(theta); t=tc.MPSCircuit(n,tensors=tt,center_position=0); ov=c.proj_with_mps(t,conj=True); return 1-jnp.real(ov*jnp.conj(ov))
vg=jax.jit(jax.value_and_grad(loss))
def fun(x):
 v,g=vg(jnp.asarray(x,dtype=jnp.float32)); jax.block_until_ready(v); jax.block_until_ready(g)
 return float(np.asarray(v)), np.asarray(g,dtype=np.float64)
for seed in range(5):
 key=jax.random.PRNGKey(seed)
 theta=np.asarray(jax.random.normal(key,(npar,),dtype=jnp.float32)*0.02,dtype=np.float64)
 t=time.time(); res=opt.minimize(fun,theta,method='L-BFGS-B',jac=True,options={'maxiter':200,'ftol':1e-10,'gtol':1e-6}); print('seed',seed,'nit',res.nit,'fid',1-res.fun,'time',time.time()-t)
